/**
 * PWA constants shared by app/manifest.ts and the root layout's viewport. Browser chrome
 * (theme bar, splash screen) cannot read CSS variables, so this mirrors --bg in
 * src/styles/tokens.css; change it there first.
 */
export const APP_BACKGROUND = "#0b0614";

/** Icons generated by scripts/generate-icons.mjs into public/icons/ */
export const PWA_ICONS = {
  any192: "/icons/icon-192.png",
  any512: "/icons/icon-512.png",
  maskable192: "/icons/maskable-192.png",
  maskable512: "/icons/maskable-512.png",
  apple: "/icons/apple-touch-icon.png",
} as const;
